/// A message of this schema, as [`decode`] found it.
#[derive(Debug, Clone, Copy)]
pub enum Decoded<'a> {
    /// `NewOrder`.
    NewOrder(NewOrderRef<'a>),
    /// `CancelOrder`.
    CancelOrder(CancelOrderRef<'a>),
    /// `ModifyOrder`.
    ModifyOrder(ModifyOrderRef<'a>),
    /// `BookRequest`.
    BookRequest(BookRequestRef<'a>),
    /// `Accepted`.
    Accepted(AcceptedRef<'a>),
    /// `Fill`.
    Fill(FillRef<'a>),
    /// `Modified`.
    Modified(ModifiedRef<'a>),
    /// `Cancelled`.
    Cancelled(CancelledRef<'a>),
    /// `Expired`.
    Expired(ExpiredRef<'a>),
    /// `Triggered`.
    Triggered(TriggeredRef<'a>),
    /// `Rejected`.
    Rejected(RejectedRef<'a>),
    /// `Book`.
    Book(BookRef<'a>),
    /// `Snapshot`.
    Snapshot(SnapshotRef<'a>),
}

/// Reads the message at the start of `bytes`: its header, then the message its template ID names. Returns the message and its length, header included.
///
/// # Errors
///
/// If the header names another schema or an unknown template, or the message doesn't fit in `bytes`.
#[allow(clippy::too_many_lines)]
pub fn decode(bytes: &[u8]) -> Result<(Decoded<'_>, usize), turbofan_sbe::SbeError> {
    let header = MessageHeader::decode(turbofan_sbe::take(bytes, 0, MessageHeader::SIZE)?);
    if header.schema_id != SCHEMA_ID {
        return Err(turbofan_sbe::SbeError::SchemaId(header.schema_id));
    }
    let body = &bytes[MessageHeader::SIZE..];
    let block_length = usize::from(header.block_length);
    let (message, len) = match header.template_id {
        1 => {
            let (message, len) = <NewOrderRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::NewOrder(message), len)
        }
        2 => {
            let (message, len) = <CancelOrderRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::CancelOrder(message), len)
        }
        3 => {
            let (message, len) = <ModifyOrderRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::ModifyOrder(message), len)
        }
        4 => {
            let (message, len) = <BookRequestRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::BookRequest(message), len)
        }
        10 => {
            let (message, len) = <AcceptedRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Accepted(message), len)
        }
        11 => {
            let (message, len) = <FillRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Fill(message), len)
        }
        12 => {
            let (message, len) = <ModifiedRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Modified(message), len)
        }
        13 => {
            let (message, len) = <CancelledRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Cancelled(message), len)
        }
        14 => {
            let (message, len) = <ExpiredRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Expired(message), len)
        }
        15 => {
            let (message, len) = <TriggeredRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Triggered(message), len)
        }
        16 => {
            let (message, len) = <RejectedRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Rejected(message), len)
        }
        17 => {
            let (message, len) = <BookRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Book(message), len)
        }
        20 => {
            let (message, len) = <SnapshotRef as turbofan_sbe::Block>::wrap(body, block_length, header.version)?;
            (Decoded::Snapshot(message), len)
        }
        id => return Err(turbofan_sbe::SbeError::UnknownTemplate(id)),
    };
    Ok((message, MessageHeader::SIZE + len))
}

fn read_group_size_encoding<'a, E: turbofan_sbe::Block<'a>>(
    bytes: &'a [u8],
    at: usize,
    version: u16,
) -> Result<(turbofan_sbe::Group<'a, E>, usize), turbofan_sbe::SbeError> {
    let dimension = GroupSizeEncoding::decode(turbofan_sbe::take(bytes, at, GroupSizeEncoding::SIZE)?);
    let at = at + GroupSizeEncoding::SIZE;
    let rest = bytes.get(at..).ok_or(turbofan_sbe::SbeError::Truncated)?;
    let (group, len) = turbofan_sbe::Group::scan(
        rest,
        turbofan_sbe::length(dimension.block_length)?,
        turbofan_sbe::length(dimension.num_in_group)?,
        version,
    )?;
    Ok((group, at + len))
}

fn write_group_size_encoding(
    out: &mut Vec<u8>,
    name: &'static str,
    block_length: usize,
    count: usize,
) -> Result<(), turbofan_sbe::SbeError> {
    let dimension = GroupSizeEncoding {
        block_length: turbofan_sbe::count(name, block_length, u16::MAX)?,
        num_in_group: turbofan_sbe::count(name, count, u16::MAX)?,
    };
    dimension.encode(turbofan_sbe::reserve(out, GroupSizeEncoding::SIZE));
    Ok(())
}

